-- Role helpers are private to the database policy layer, not exposed as PostgREST RPC endpoints.
create schema if not exists private;
revoke all on schema private from public,anon;
grant usage on schema private to authenticated;
create or replace function private.qaaga_is_super_admin() returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$ select coalesce((auth.jwt()->'app_metadata'->>'role')='admin',false) or exists(select 1 from public.user_role_assignments u where u.user_id=auth.uid() and u.role='super_admin' and u.is_active and (u.expires_at is null or u.expires_at>now())); $$;
create or replace function private.qaaga_has_role(p_role text) returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$ select private.qaaga_is_super_admin() or exists(select 1 from public.user_role_assignments u where u.user_id=auth.uid() and u.role=p_role and u.is_active and (u.expires_at is null or u.expires_at>now())); $$;
create or replace function private.qaaga_can_manage_property(p_property_id text) returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$ select private.qaaga_is_super_admin() or exists(select 1 from public.properties p where p.id=p_property_id and lower(p.host_email)=lower(coalesce(auth.jwt()->>'email',''))) or exists(select 1 from public.property_staff_assignments s where s.property_id=p_property_id and s.user_id=auth.uid() and s.is_active); $$;
create or replace function private.qaaga_has_property_role(p_property_id text,p_role text) returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$ select private.qaaga_is_super_admin() or exists(select 1 from public.property_staff_assignments s where s.property_id=p_property_id and s.user_id=auth.uid() and s.role=p_role and s.is_active); $$;
create or replace function private.qaaga_can_access_ticket(p_ticket_id uuid) returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$ select private.qaaga_is_super_admin() or private.qaaga_has_role('support') or exists(select 1 from public.support_tickets t where t.id=p_ticket_id and (t.requester_id=auth.uid() or t.assigned_to=auth.uid())); $$;
create or replace function private.qaaga_guard_booking_update() returns trigger language plpgsql security definer set search_path=public,private,pg_temp as $$
declare v_email text:=lower(coalesce(auth.jwt()->>'email',''));
begin
 if private.qaaga_is_super_admin() then return new; end if;
 if v_email=lower(old.customer_email) then
  if new.status<>'Cancelled' or (to_jsonb(new)-array['status','cancellation_reason','updated_at','cancelled_by','cancelled_at'])<>(to_jsonb(old)-array['status','cancellation_reason','updated_at','cancelled_by','cancelled_at']) then raise exception 'Customers may only cancel their own booking; booking details are immutable.'; end if;
  new.cancelled_by:='customer';new.cancelled_at:=coalesce(new.cancelled_at,now());return new;
 end if;
 if v_email=lower(old.host_email) or private.qaaga_can_manage_property(old.property_id) then
  if new.status not in ('Accepted','Confirmed','Rejected','Cancelled','Completed') or (to_jsonb(new)-array['status','cancellation_reason','updated_at','cancelled_by','cancelled_at'])<>(to_jsonb(old)-array['status','cancellation_reason','updated_at','cancelled_by','cancelled_at']) then raise exception 'Hosts and assigned staff may only update booking status and cancellation metadata.'; end if;
  if new.status='Cancelled' then new.cancelled_by:='host';new.cancelled_at:=coalesce(new.cancelled_at,now());end if;return new;
 end if;
 raise exception 'Not authorized to update this booking.';
end; $$;
grant execute on function private.qaaga_is_super_admin() to authenticated;
grant execute on function private.qaaga_has_role(text) to authenticated;
grant execute on function private.qaaga_can_manage_property(text) to authenticated;
grant execute on function private.qaaga_has_property_role(text,text) to authenticated;
grant execute on function private.qaaga_can_access_ticket(uuid) to authenticated;
grant execute on function private.qaaga_guard_booking_update() to authenticated;
revoke all on function public.qaaga_is_super_admin() from public,anon,authenticated;
revoke all on function public.qaaga_has_role(text) from public,anon,authenticated;
revoke all on function public.qaaga_can_manage_property(text) from public,anon,authenticated;
revoke all on function public.qaaga_has_property_role(text,text) from public,anon,authenticated;
revoke all on function public.qaaga_can_access_ticket(uuid) from public,anon,authenticated;
revoke all on function public.qaaga_guard_booking_update() from public,anon,authenticated;
drop policy if exists qaaga_role_assignment_read on public.user_role_assignments;
create policy qaaga_role_assignment_read on public.user_role_assignments for select to authenticated using((select auth.uid())=user_id or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_role_assignment_admin_write on public.user_role_assignments;
create policy qaaga_role_assignment_admin_write on public.user_role_assignments for all to authenticated using((select private.qaaga_is_super_admin())) with check((select private.qaaga_is_super_admin()));
drop policy if exists qaaga_property_staff_read on public.property_staff_assignments;
create policy qaaga_property_staff_read on public.property_staff_assignments for select to authenticated using((select auth.uid())=user_id or (select private.qaaga_is_super_admin()) or exists(select 1 from public.properties p where p.id=property_id and lower(p.host_email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists qaaga_property_staff_manage on public.property_staff_assignments;
create policy qaaga_property_staff_manage on public.property_staff_assignments for all to authenticated using((select private.qaaga_is_super_admin()) or exists(select 1 from public.properties p where p.id=property_id and lower(p.host_email)=lower(coalesce((select auth.jwt()->>'email'),'')))) with check((select private.qaaga_is_super_admin()) or exists(select 1 from public.properties p where p.id=property_id and lower(p.host_email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists qaaga_support_ticket_read on public.support_tickets;
create policy qaaga_support_ticket_read on public.support_tickets for select to authenticated using(requester_id=(select auth.uid()) or assigned_to=(select auth.uid()) or (select private.qaaga_has_role('support')) or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_support_ticket_create on public.support_tickets;
create policy qaaga_support_ticket_create on public.support_tickets for insert to authenticated with check(requester_id=(select auth.uid()) and lower(requester_email)=lower(coalesce((select auth.jwt()->>'email'),'')));
drop policy if exists qaaga_support_ticket_staff_update on public.support_tickets;
create policy qaaga_support_ticket_staff_update on public.support_tickets for update to authenticated using((select private.qaaga_has_role('support')) or (select private.qaaga_is_super_admin())) with check((select private.qaaga_has_role('support')) or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_support_messages_read on public.support_ticket_messages;
create policy qaaga_support_messages_read on public.support_ticket_messages for select to authenticated using((select private.qaaga_can_access_ticket(ticket_id)) and (not internal_note or (select private.qaaga_has_role('support')) or (select private.qaaga_is_super_admin())));
drop policy if exists qaaga_support_messages_create on public.support_ticket_messages;
create policy qaaga_support_messages_create on public.support_ticket_messages for insert to authenticated with check(sender_id=(select auth.uid()) and (select private.qaaga_can_access_ticket(ticket_id)) and (not internal_note or (select private.qaaga_has_role('support')) or (select private.qaaga_is_super_admin())));
drop policy if exists qaaga_service_fee_ledger_read on public.service_fee_ledger;
create policy qaaga_service_fee_ledger_read on public.service_fee_ledger for select to authenticated using((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin()) or exists(select 1 from public.bookings b where b.id=booking_id and lower(b.customer_email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists qaaga_service_fee_ledger_finance_write on public.service_fee_ledger;
create policy qaaga_service_fee_ledger_finance_write on public.service_fee_ledger for all to authenticated using((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin())) with check((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_properties_staff_read on public.properties;
create policy qaaga_properties_staff_read on public.properties for select to authenticated using((select private.qaaga_can_manage_property(id)));
drop policy if exists qaaga_properties_manager_update on public.properties;
create policy qaaga_properties_manager_update on public.properties for update to authenticated using((select private.qaaga_has_property_role(id,'property_manager'))) with check((select private.qaaga_has_property_role(id,'property_manager')));
drop policy if exists qaaga_availability_staff_manage on public.property_availability;
create policy qaaga_availability_staff_manage on public.property_availability for all to authenticated using((select private.qaaga_can_manage_property(property_id))) with check((select private.qaaga_can_manage_property(property_id)));
drop policy if exists qaaga_bookings_staff_read on public.bookings;
create policy qaaga_bookings_staff_read on public.bookings for select to authenticated using((select private.qaaga_has_role('support')) or (select private.qaaga_can_manage_property(property_id)));
drop policy if exists qaaga_bookings_staff_update on public.bookings;
create policy qaaga_bookings_staff_update on public.bookings for update to authenticated using((select private.qaaga_can_manage_property(property_id))) with check((select private.qaaga_can_manage_property(property_id)));
drop policy if exists qaaga_payment_finance_read on public.payment_records;
create policy qaaga_payment_finance_read on public.payment_records for select to authenticated using((select private.qaaga_has_role('finance')) or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_identity_verification_read on public.identity_verifications;
create policy qaaga_identity_verification_read on public.identity_verifications for select to authenticated using((select private.qaaga_has_role('verification')) or (select private.qaaga_is_super_admin()));
drop policy if exists qaaga_identity_verification_review on public.identity_verifications;
create policy qaaga_identity_verification_review on public.identity_verifications for update to authenticated using((select private.qaaga_has_role('verification')) or (select private.qaaga_is_super_admin())) with check((select private.qaaga_has_role('verification')) or (select private.qaaga_is_super_admin()));
drop trigger if exists qaaga_guard_booking_update on public.bookings;
create trigger qaaga_guard_booking_update before update on public.bookings for each row execute function private.qaaga_guard_booking_update();
create index if not exists idx_user_role_assigned_by on public.user_role_assignments(assigned_by);
create index if not exists idx_property_staff_assigned_by on public.property_staff_assignments(assigned_by);
create index if not exists idx_support_ticket_booking on public.support_tickets(booking_id);
create index if not exists idx_support_message_sender on public.support_ticket_messages(sender_id);
create index if not exists idx_service_fee_created_by on public.service_fee_ledger(created_by);
